(function(root){
'use strict';
const trapDefaults={designer:'',area:'',stationId:'',station:'',lambda:'',kappa:'',theta:'',eta:'',c:'',tc:'',storageDepth:'',baseWidth:'',baseLength:'',spillwayWidth:'',spillwayHead:'',spillwayCoefficient:''};
const basinDefaults={designer:'',area:'',basinType:'',runoffClass:'',sizingTc:'',stationId:'',station:'',lambda:'',kappa:'',theta:'',eta:'',tc:'',c:'',settlingDepth:'',surfaceWidth:'',orificeDiameter:'',orificeCount:'',orificeHead:'',spillwayWidth:'',spillwayHead:'',spillwayCoefficient:''};
let trap={...trapDefaults},basin={...basinDefaults};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=x=>x===''||x==null?NaN:Number(x),f=(x,n=2)=>Number.isFinite(x)?x.toFixed(n):'—';
const stations=()=>root.MSMA_STATIONS||[];
function options(selected){return `<option value="" disabled ${selected?'':'selected'}>Select rainfall station</option>`+[...new Set(stations().map(s=>s.state))].map(state=>`<optgroup label="${esc(state)}">${stations().filter(s=>s.state===state).map(s=>`<option value="${s.id}" ${s.id===selected?'selected':''}>${esc(s.name)} (${s.id})</option>`).join('')}</optgroup>`).join('')}
function applyStation(state,id){const s=stations().find(x=>x.id===id);if(s)Object.assign(state,{stationId:s.id,station:s.name,lambda:s.lambda,kappa:s.kappa,theta:s.theta,eta:s.eta})}
function rainfall(state,ari=10,calculatedTc){const tc=Number.isFinite(calculatedTc)?calculatedTc:num(state.tc),i=num(state.lambda)*ari**num(state.kappa)/(tc/60+num(state.theta))**num(state.eta),q=num(state.c)*i*num(state.area)/360;return {i,q}}
function volumeFrustum(l,b,h,z=2){const at=(l+2*z*h)*(b+2*z*h),ab=l*b;return h/3*(ab+at+Math.sqrt(ab*at))}
function calcTrap(s){const keys=['area','c','tc','storageDepth','baseWidth','baseLength','spillwayWidth','spillwayHead','spillwayCoefficient'];const missing=keys.filter(k=>!Number.isFinite(num(s[k]))||num(s[k])<=0);if(!s.stationId)missing.push('stationId');if(!String(s.designer).trim())missing.push('designer');if(missing.length)return {valid:false,missing};const A=num(s.area),tc=num(s.tc),ys=num(s.storageDepth),b=num(s.baseWidth),l=num(s.baseLength),fb=.3,z=2,topB=b+2*z*(ys+fb),topL=l+2*z*(ys+fb),storageTopB=b+2*z*ys,storageTopL=l+2*z*ys,v=topL*topB*ys,required=125*A,pool=required/2,ratio=topL/topB,rain=rainfall(s,10,tc),spill=num(s.spillwayCoefficient)*num(s.spillwayWidth)*num(s.spillwayHead)**1.5,totalDepth=ys+fb;const checks={area:A<=2,storage:v>=required,ratio:ratio>=2,depth:totalDepth>=1&&totalDepth<=2,spill:spill>=rain.q};return {valid:true,A,tc,ys,b,l,fb,z,topB,topL,storageTopB,storageTopL,v,required,pool,ratio,totalDepth,...rain,spill,checks,pass:Object.values(checks).every(Boolean)}}
const dryTable={10:[333,400],20:[250,300],30:[200,240],45:[158,190],60:[121,145]};
function solveY2(v,w,l,z=2){let lo=0,hi=10;for(let n=0;n<80;n++){const y=(lo+hi)/2,got=z*z*y**3-z*y*y*(w+l)+y*w*l;got<v?lo=y:hi=y}return (lo+hi)/2}
function calcBasin(s){const common=['area','tc','c','settlingDepth','surfaceWidth','spillwayWidth','spillwayHead','spillwayCoefficient'];const missing=common.filter(k=>!Number.isFinite(num(s[k]))||num(s[k])<=0);if(!s.basinType)missing.push('basinType');if(!s.stationId)missing.push('stationId');if(!String(s.designer).trim())missing.push('designer');if(s.basinType==='dry'&&!dryTable[s.sizingTc])missing.push('sizingTc');if(s.basinType==='wet'&&!s.runoffClass)missing.push('runoffClass');if(s.basinType==='dry')['orificeDiameter','orificeCount','orificeHead'].forEach(k=>{if(!Number.isFinite(num(s[k]))||num(s[k])<=0)missing.push(k)});if(missing.length)return {valid:false,missing};const A=num(s.area),y1=num(s.settlingDepth),w1=num(s.surfaceWidth),z=2,fb=.3;let surfaceRate,totalRate;if(s.basinType==='dry'){[surfaceRate,totalRate]=dryTable[s.sizingTc]}else{surfaceRate=NaN;totalRate=s.runoffClass==='moderate'?435:510}const total=totalRate*A,v1=total/2,v2=total/2,l1=v1/(w1*y1),y2=solveY2(v2,w1,l1,z),baseW=w1-2*z*(y1/2+y2),baseL=l1-2*z*(y1/2+y2),avgSurface=w1*l1,rain=rainfall(s),orifice=s.basinType==='dry'?.6*(num(s.orificeCount)*Math.PI*num(s.orificeDiameter)**2/4)*Math.sqrt(2*9.81*num(s.orificeHead)):0,requiredQ=Math.max(0,rain.q-orifice),spill=num(s.spillwayCoefficient)*num(s.spillwayWidth)*num(s.spillwayHead)**1.5,ratio=l1/w1,depth=y1+y2+fb+num(s.spillwayHead);const checks={area:A>=2,settling:y1>=.6,sediment:y2>=.3,ratio:ratio>=2,slender:l1/y1<=200,geometry:baseW>0&&baseL>0,surface:s.basinType!=='dry'||avgSurface>=surfaceRate*A,spill:spill>=requiredQ};return {valid:true,A,y1,w1,z,fb,surfaceRate,totalRate,total,v1,v2,l1,y2,baseW,baseL,avgSurface,ratio,depth,...rain,orifice,requiredQ,spill,checks,pass:Object.values(checks).every(Boolean)}}
function field(prefix,key,label,unit=''){return `<label class="drain-field"><span>${label}${unit?' ('+unit+')':''}</span><input name="${key}" id="${prefix}-${key}" type="number" inputmode="decimal" step="any" min="0" value="${esc((prefix==='st'?trap:basin)[key])}" required></label>`}
const pair=(label,value,unit='')=>`<div class="calc-pair"><span>${label}</span><span>${value}${unit?' '+unit:''}</span></div>`;
function statusRows(checks){const names={area:'Contributing area',storage:'Storage volume',ratio:'Length : width',depth:'Overall depth',spill:'Emergency spillway',settling:'Settling-zone depth',sediment:'Sediment-zone depth',slender:'Length : settling depth',geometry:'Basin geometry',surface:'Average surface area'};return Object.entries(checks).map(([k,v])=>`<p class="check-line ${v?'':'check-fail'}">${v?'✓':'✕'} ${names[k]}</p>`).join('')}
function trapDiagram(r){const ok=r.valid,fail=ok&&!r.pass,rimY=48,baseY=258,storageY=ok?rimY+(baseY-rimY)*r.fb/r.totalDepth:120,poolY=ok?baseY-(baseY-storageY)/2:190;return `<svg class="escp-diagram escp-section" viewBox="0 0 680 340" role="img" aria-label="Sediment trap cross-section showing storage, permanent pool, freeboard and spillway"><path class="earth" d="M25 ${rimY}H145L230 ${baseY}H450L535 ${rimY}H655V305H25Z"/><path class="water ${fail?'fail-water':''}" d="M${ok?145+85*r.fb/r.totalDepth:175} ${storageY}H${ok?535-85*r.fb/r.totalDepth:505}L450 ${baseY}H230Z"/><path d="M145 ${rimY}L230 ${baseY}H450L535 ${rimY}" fill="none" stroke="#28493d" stroke-width="3"/><path d="M${ok?230-85*(poolY-baseY)/(rimY-baseY):205} ${poolY}H${ok?450+85*(poolY-baseY)/(rimY-baseY):475}" fill="none" stroke="#157f93" stroke-width="2" stroke-dasharray="8 6"/><path d="M300 ${rimY}v22h80V${rimY}" fill="#fff" stroke="#28493d" stroke-width="2"/><path class="dim" d="M230 282H450M570 ${rimY}V${storageY}M600 ${storageY}V${baseY}"/><text x="340" y="314" text-anchor="middle">Base width, WB = ${ok?f(r.b):'—'} m</text><text x="584" y="${(rimY+storageY)/2}" transform="rotate(90 584 ${(rimY+storageY)/2})" text-anchor="middle">Freeboard 0.30 m</text><text x="614" y="${(storageY+baseY)/2}" transform="rotate(90 614 ${(storageY+baseY)/2})" text-anchor="middle">Storage depth = ${ok?f(r.ys):'—'} m</text><text x="340" y="${poolY-8}" text-anchor="middle">Permanent pool · ½ storage</text><text x="340" y="39" text-anchor="middle">Emergency spillway · B = ${ok?esc(trap.spillwayWidth):'—'} m</text><path d="M466 174h50v-25z" fill="none" stroke="#28493d"/><text x="491" y="198" text-anchor="middle">2H</text><text x="524" y="163">1V</text>${fail?'<text x="340" y="333" text-anchor="middle" fill="#a0372b">Review: one or more MSMA checks fail</text>':''}</svg>`}
function basinDiagram(r){const ok=r.valid,fail=ok&&!r.pass;return `<svg class="escp-diagram escp-section" viewBox="0 0 620 300" role="img" aria-label="Sediment basin cross-section"><path class="earth" d="M20 60H130L215 250H405L490 60H600V285H20Z"/><path class="water ${fail?'fail-water':''}" d="M166 140H454L405 250H215Z"/><path d="M130 60L215 250H405L490 60" fill="none" stroke="#28493d" stroke-width="3"/><path d="M215 215H405" stroke="#785d2d" stroke-dasharray="7 5"/><text x="310" y="238" text-anchor="middle">Sediment storage</text><text x="310" y="132" text-anchor="middle">Settling zone</text><path d="M419 158h50v-25z" fill="none" stroke="#28493d"/><text x="444" y="181" text-anchor="middle">2H</text><text x="477" y="148">1V</text><text x="310" y="284" text-anchor="middle">Base ${ok?f(r.baseL)+' × '+f(r.baseW):'—'} m</text>${fail?'<text x="310" y="38" text-anchor="middle" fill="#a0372b">Review: one or more MSMA checks fail</text>':''}</svg>`}
function planDiagram(r,kind){const trapPlan=kind==='trap',length=trapPlan?r.topL:r.l1,width=trapPlan?r.topB:r.w1;return `<svg class="escp-diagram escp-plan" viewBox="0 0 620 255" role="img" aria-label="${trapPlan?'Sediment trap':'Sediment basin'} plan view"><defs><marker id="plan-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0L10 5L0 10Z" fill="#168ba1"/></marker></defs><rect x="105" y="48" width="410" height="160" rx="35" class="earth"/><rect x="140" y="72" width="340" height="112" rx="26" class="water"/><path class="water flow" d="M25 128H195M300 128H585" fill="none" marker-end="url(#plan-arrow)"/><text x="68" y="112" text-anchor="middle">Inlet</text><text x="552" y="112" text-anchor="middle">Spillway</text><text x="310" y="28" text-anchor="middle">Length = ${f(length)} m</text><text x="500" y="132" transform="rotate(90 500 132)" text-anchor="middle">Width = ${f(width)} m</text></svg>`}
function page(title,n,total,project,designer,rows){const date=new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'short',year:'numeric'}).format(new Date());return `<article class="a4-sheet"><div class="sheet-head"><h3>Calculation Sheet</h3><div>Project: <b>${project}</b><small>Sheet ${n} / ${total}</small></div></div><div class="sheet-meta"><div>Title: <b>ESCP DESIGN</b><br>${title}</div><div>Designed by: ${esc(designer||'—')}<br>Date: ${date}</div></div><table class="calc-table"><colgroup><col style="width:13%"><col style="width:73%"><col style="width:14%"></colgroup><thead><tr><th>REF.</th><th>CALCULATION</th><th>REMARK</th></tr></thead><tbody>${rows}</tbody></table><div class="sheet-foot">NADI PreDesign · Cross-checked against MSMA 2nd Edition, Chapter 12</div></article>`}
const row=(ref,calc,remark='')=>`<tr><td class="calc-ref">${ref}</td><td>${calc}</td><td class="calc-remark">${remark}</td></tr>`;
function trapReport(r){const project=esc(document.querySelector('#project-name').value||'—'),v=x=>`<mark>${f(x)}</mark>`;return page('SEDIMENT TRAP (SILT TRAP)',1,4,project,trap.designer,row('Input','<h4>DESIGN INPUT</h4>'+pair('Catchment area, A',v(r.A),'ha')+pair('Rainfall station',esc(trap.station))+pair('Return period','10 years')+pair('Quality storm','First 50 mm'))+row('MSMA 2<br>Table 12.15','<h4>DESIGN CRITERIA</h4><div class="criteria">Maximum contributing area 2 ha; storage 125 m³/ha; permanent pool half the total storage; minimum length:width 2:1; minimum total depth 1 m; depth above 2 m is not recommended; inside slope 2H:1V; emergency spillway safely bypasses the 10-year ARI flow.</div>'))+
page('SEDIMENT TRAP (SILT TRAP)',2,4,project,trap.designer,row('MSMA 2<br>Table 12.15','<h4>STORAGE AND GEOMETRY</h4>'+pair('Required storage = 125A',v(r.required),'m³')+pair('Permanent pool = 0.5Vrequired',v(r.pool),'m³')+pair('Storage depth',v(r.ys),'m')+pair('Freeboard','0.30 m')+pair('Provided volume = LT × WT × y₁',v(r.v),'m³')+pair('Top length × width',`${f(r.topL)} × ${f(r.topB)} m`)+pair('Length : width',`${f(r.ratio)} : 1`),`Storage: ${r.checks.storage?'OK':'NOT OK'}<br>Ratio: ${r.checks.ratio?'OK':'NOT OK'}`)+row('Section',trapDiagram(r),'Inside slope 2H:1V'))+
page('SEDIMENT TRAP (SILT TRAP)',3,4,project,trap.designer,row('MSMA 2<br>Eq. 2.2','<h4>RAINFALL INTENSITY</h4><p>i = λT<sup>κ</sup> / (t + θ)<sup>η</sup></p>'+pair('ARI, T','10 years')+pair('Time of concentration, tc',v(r.tc),'min')+pair('Duration, t',f(r.tc/60,4),'hour')+pair('Rainfall intensity, i',v(r.i),'mm/hr'))+row('MSMA 2<br>Eq. 2.3','<h4>PEAK FLOW</h4><p>Q<sub>10</sub> = CiA / 360</p>'+pair('Runoff coefficient, C',esc(trap.c))+pair('Q10',v(r.q),'m³/s')))+
page('SEDIMENT TRAP (SILT TRAP)',4,4,project,trap.designer,row('Spillway','<h4>EMERGENCY SPILLWAY CHECK</h4><p>Q = C<sub>sp</sub>B H<sup>3/2</sup></p>'+pair('Spillway coefficient',esc(trap.spillwayCoefficient))+pair('Width, B',esc(trap.spillwayWidth),'m')+pair('Head, H',esc(trap.spillwayHead),'m')+pair('Spillway capacity',v(r.spill),'m³/s')+pair('10-year peak flow',v(r.q),'m³/s'),r.checks.spill?'<b>OK</b>':'<b>NOT OK</b>')+row('Plan',planDiagram(r,'trap'),'Schematic plan view')+row('Conclusion','<h4>MSMA CHECK SUMMARY</h4>'+statusRows(r.checks),r.pass?'<b>PASS</b>':'<b>REVIEW</b>'))}
function basinReport(r){const project=esc(document.querySelector('#project-name').value||'—'),v=x=>`<mark>${f(x)}</mark>`,kind=basin.basinType==='dry'?'DRY SEDIMENT BASIN':'WET SEDIMENT BASIN';return page(kind,1,5,project,basin.designer,row('Input','<h4>'+kind+'</h4>'+pair('Catchment area',v(r.A),'ha')+pair('Basin selection',kind)+pair('Rainfall station',esc(basin.station))+pair('Return period','10 years')+pair('Quality storm','First 50 mm'))+row('MSMA 2<br>Tables 12.16–12.17','<h4>SELECTION AND CRITERIA</h4><div class="criteria">Dry basin: coarse sand/sandy loam, HSG A. Wet basin: fine loam/clay, HSG B. Dispersible fine clay in HSG C/D requires a wet basin with assisted flocculation. Minimum contributing area 2 ha; half the total volume is allocated to settling and half to sediment storage.</div>'))+
page(kind,2,5,project,basin.designer,row('MSMA 2<br>Table '+(basin.basinType==='dry'?'12.18':'12.19'),'<h4>STORAGE REQUIREMENT</h4>'+pair('Total storage rate',v(r.totalRate),'m³/ha')+(basin.basinType==='dry'?pair('Minimum surface rate',v(r.surfaceRate),'m²/ha'):'')+pair('Total storage',v(r.total),'m³')+pair('Settling zone, V1',v(r.v1),'m³')+pair('Sediment zone, V2',v(r.v2),'m³'),basin.basinType==='wet'?'Table 12.19 values are treated as volume, in m³/ha.':'Sizing duration from Table 12.18.')+row('Geometry','<h4>BASIN GEOMETRY</h4>'+pair('Surface length × width',`${f(r.l1)} × ${f(r.w1)} m`)+pair('Length : width',`${f(r.ratio)} : 1`)+pair('Settling depth',v(r.y1),'m')+pair('Sediment depth',v(r.y2),'m')+pair('Base length × width',`${f(r.baseL)} × ${f(r.baseW)} m`),`Side slopes 2H:1V`))+
page(kind,3,5,project,basin.designer,row('Cross-section',basinDiagram(r),`Settling depth ≥ 0.60 m<br>Sediment depth ≥ 0.30 m`)+row('Checks','<h4>GEOMETRY CHECKS</h4>'+statusRows({area:r.checks.area,settling:r.checks.settling,sediment:r.checks.sediment,ratio:r.checks.ratio,slender:r.checks.slender,geometry:r.checks.geometry,surface:r.checks.surface}),r.pass?'Proceed':'Review inputs'))+
page(kind,4,5,project,basin.designer,row('MSMA 2<br>Eq. 2.2','<h4>RAINFALL INTENSITY</h4><p>i = λT<sup>κ</sup> / (t + θ)<sup>η</sup></p>'+pair('ARI','10 years')+pair('Rainfall intensity',v(r.i),'mm/hr'))+row('MSMA 2<br>Eq. 2.3','<h4>10-YEAR PEAK FLOW</h4><p>Q<sub>10</sub> = CiA / 360</p>'+pair('Q10',v(r.q),'m³/s'))+row('Outlet','<h4>PRIMARY OUTLET</h4>'+pair('Orifice discharge',v(r.orifice),'m³/s')+pair('Required spillway flow',v(r.requiredQ),'m³/s'),basin.basinType==='dry'?'Orifice equation uses Cd = 0.60':'Wet-basin example uses no riser deduction.'))+
page(kind,5,5,project,basin.designer,row('Spillway','<h4>EMERGENCY SPILLWAY</h4><p>Q = C<sub>sp</sub>B H<sup>3/2</sup></p>'+pair('Spillway capacity',v(r.spill),'m³/s')+pair('Required flow',v(r.requiredQ),'m³/s'),r.checks.spill?'<b>OK</b>':'<b>NOT OK</b>')+row('Plan',planDiagram(r,'basin'),'Schematic plan view')+row('Conclusion','<h4>MSMA CHECK SUMMARY</h4>'+statusRows(r.checks),r.pass?'<b>PASS</b>':'<b>REVIEW</b>'))}
function referenceDialogs(){return `<dialog id="escp-criteria" class="reference-dialog"><div class="reference-dialog-head"><div><h2>MSMA ESCP criteria</h2><p>MSMA 2nd Edition · Chapter 12</p></div><button type="button" data-close>✕</button></div><table class="escp-reference"><thead><tr><th>Facility</th><th>Applicable condition</th><th>Core criteria</th></tr></thead><tbody><tr><td>Sediment Trap</td><td>Contributing area up to 2 ha</td><td>125 m³/ha; half permanent pool; L:W ≥ 2; depth ≥ 1 m; inside slope 2H:1V.</td></tr><tr><td>Dry Sediment Basin</td><td>Coarse sand/sandy loam; &lt;33% finer than 0.02 mm; HSG A</td><td>Table 12.18; drain within 24 h.</td></tr><tr><td>Wet Sediment Basin</td><td>Fine loam/clay; &gt;33% finer than 0.02 mm; HSG B</td><td>Table 12.19; drain within 36 h.</td></tr><tr><td>Wet + flocculation</td><td>Dispersible fine clay &gt;10%; HSG C/D</td><td>Assisted flocculation required.</td></tr></tbody></table><h3>Dry basin · Table 12.18</h3><table class="escp-reference"><tr><th>tc (min)</th><th>10</th><th>20</th><th>30</th><th>45</th><th>60</th></tr><tr><td>Surface (m²/ha)</td><td>333</td><td>250</td><td>200</td><td>158</td><td>121</td></tr><tr><td>Volume (m³/ha)</td><td>400</td><td>300</td><td>240</td><td>190</td><td>145</td></tr></table><h3>Wet basin · Table 12.19 · 50 mm storm</h3><table class="escp-reference"><tr><th>Runoff potential</th><th>Settling-zone volume</th><th>Total volume</th></tr><tr><td>Moderate–high</td><td>290 m³/ha</td><td>435 m³/ha</td></tr><tr><td>Very high</td><td>340 m³/ha</td><td>510 m³/ha</td></tr></table></dialog><dialog id="escp-runoff" class="reference-dialog"><div class="reference-dialog-head"><div><h2>Runoff Coefficient, C</h2><p>MSMA 2nd Edition · Table 2.5 · Minor System, ARI up to 10 years</p></div><button type="button" data-close>✕</button></div><div class="reference-image-scroll"><img src="assets/msma-table-2-5.png" width="1485" height="1191" alt="MSMA Table 2.5 runoff coefficients by land use"></div></dialog><dialog id="escp-horton" class="reference-dialog"><div class="reference-dialog-head"><div><h2>Horton’s Roughness, n</h2><p>MSMA 2nd Edition · Table 2.2</p></div><button type="button" data-close>✕</button></div><table class="escp-reference"><thead><tr><th>Land surface</th><th>Horton roughness, n</th></tr></thead><tbody><tr><td>Paved</td><td>0.015</td></tr><tr><td>Bare soil</td><td>0.0275</td></tr><tr><td>Poorly grassed</td><td>0.035</td></tr><tr><td>Average grassed</td><td>0.045</td></tr><tr><td>Densely grassed</td><td>0.060</td></tr></tbody></table></dialog>`}
function bindDialog(container){for(const [triggerName,id] of [['criteria','escp-criteria'],['runoff','escp-runoff'],['horton','escp-horton']]){const trigger=container.querySelector(`[data-${triggerName}]`),dialog=container.querySelector('#'+id);if(!trigger||!dialog)continue;const close=dialog.querySelector('[data-close]');trigger.onclick=()=>dialog.showModal();close.onclick=()=>dialog.close()}}
function mountTrap(container){container.innerHTML=`<a class="back" href="#module/1">← Back to Erosion and Sediment Control</a><div class="drain-toolbar"><div><h2>Sediment Trap (Silt Trap)</h2><p>Calculation layout follows the Excel Silt Trap sheet and is checked against MSMA Chapter 12.</p></div><button class="drain-button" id="st-print" disabled>Print / Save PDF · A4</button></div><div class="drain-layout"><form class="drain-form"><fieldset><legend>Sheet Information</legend><div class="drain-fields"><label class="drain-field"><span>Prepared by</span><input name="designer" value="${esc(trap.designer)}" required></label></div></fieldset><div class="escp-fixed">Return period, ARI — <b>10 years</b> · Quality storm — <b>first 50 mm</b></div><fieldset><legend>Catchment & Rainfall</legend><div class="drain-fields">${field('st','area','Contributing area, A','ha')}${field('st','c','Runoff coefficient, C')}</div><button class="table-trigger" type="button" data-runoff>View runoff coefficient table · MSMA 2.5</button><label class="drain-field" style="margin-top:17px"><span>Rainfall station / IDF source</span><select name="stationId" required>${options(trap.stationId)}</select></label></fieldset><fieldset><legend>Time of Concentration</legend><div id="st-tc-source" class="escp-import"></div></fieldset><fieldset><legend>Storage & Geometry</legend><div class="escp-fixed">Freeboard — <b>0.30 m</b> · Inside side slope — <b>2H:1V</b></div><div class="drain-fields">${field('st','storageDepth','Storage depth, y₁','m')}${field('st','baseWidth','Base width, WB','m')}${field('st','baseLength','Base length, LB','m')}</div></fieldset><fieldset><legend>Emergency Spillway</legend><div class="drain-fields">${field('st','spillwayWidth','Width, B','m')}${field('st','spillwayHead','Design head, Hp','m')}${field('st','spillwayCoefficient','Coefficient, Csp')}</div></fieldset><button class="table-trigger" type="button" data-criteria>View exact MSMA ESCP criteria and sizing tables</button><p id="st-validation"></p></form><div class="drain-results"><section class="result-panel"><h2>Calculation Results</h2><div id="st-results">Complete all inputs.</div></section><section class="result-panel"><h2>Cross-Section</h2><div id="st-diagram">${trapDiagram({valid:false})}</div></section></div></div><section class="calculation-preview"><div class="drain-toolbar"><div><h2>Calculation Sheet</h2><p>4 A4 pages · Excel REF. / CALCULATION / REMARK format</p></div></div><div id="st-report" class="escp-report"></div></section>${referenceDialogs()}`;const form=container.querySelector('form');form.oninput=e=>{if(!e.target.name)return;e.target.name==='stationId'?applyStation(trap,e.target.value):trap[e.target.name]=e.target.value;updateTrap(container)};container.querySelector('#st-print').onclick=()=>{document.body.classList.add('printing-escp');window.print()};bindDialog(container);updateTrap(container)}
function updateTrap(c){const earth=root.EarthDrain&&root.EarthDrain.calculate(root.EarthDrain.getState()),sourceReady=Boolean(earth&&earth.valid);trap.tc=sourceReady?earth.tc:'';const source=c.querySelector('#st-tc-source');if(source)source.innerHTML=sourceReady?`<div class="escp-source-ok"><span>Imported from Temp Earth Drain</span><strong>${f(earth.tc)} min</strong><small>tₒ ${f(earth.to)} min + tch ${f(earth.tch)} min</small></div>`:`<div class="escp-source-missing"><span>Temp Earth Drain calculation is incomplete.</span><a href="#module/0/0">Complete Temp Earth Drain →</a></div>`;const r=calcTrap(trap);c.querySelector('#st-print').disabled=!r.valid;c.querySelector('#st-validation').textContent=r.valid?'':sourceReady?'Complete all red fields.':'Complete Temp Earth Drain to import the time of concentration.';c.querySelector('#st-results').innerHTML=r.valid?`<div class="drain-metrics"><div><span>Time of concentration</span><strong>${f(r.tc)} <small>min</small></strong></div><div><span>Required storage</span><strong>${f(r.required)} <small>m³</small></strong></div><div><span>Provided storage</span><strong>${f(r.v)} <small>m³</small></strong></div><div><span>Q10 / Spillway</span><strong>${f(r.q,3)} / ${f(r.spill,3)} <small>m³/s</small></strong></div></div>${statusRows(r.checks)}`:'<p>Complete all inputs to calculate.</p>';c.querySelector('#st-diagram').innerHTML=trapDiagram(r);c.querySelector('#st-report').innerHTML=r.valid?trapReport(r):'';root.dispatchEvent(new CustomEvent('nadi:module-status',{detail:{key:'1/0',status:!r.valid?'incomplete':r.pass?'passed':'review'}}))}
function mountBasin(container){container.innerHTML=`<a class="back" href="#module/1">← Back to Erosion and Sediment Control</a><div class="drain-toolbar"><div><h2>Sediment Basin</h2><p>Select the basin type from MSMA Table 12.16, then complete the sizing inputs.</p></div><button class="drain-button" id="sb-print" disabled>Print / Save PDF · A4</button></div><div class="drain-layout"><form class="drain-form"><fieldset><legend>Sheet Information</legend><div class="drain-fields"><label class="drain-field"><span>Prepared by</span><input name="designer" value="${esc(basin.designer)}" required></label></div></fieldset><div class="escp-fixed">Return period, ARI — <b>10 years</b> · Quality storm — <b>first 50 mm</b></div><fieldset><legend>Basin Selection</legend><div class="escp-choice"><label><input type="radio" name="basinType" value="dry" ${basin.basinType==='dry'?'checked':''} required> Dry sediment basin</label><label><input type="radio" name="basinType" value="wet" ${basin.basinType==='wet'?'checked':''}> Wet sediment basin</label></div><div id="sb-type-fields"></div></fieldset><fieldset><legend>Catchment & Rainfall</legend><div class="drain-fields">${field('sb','area','Contributing area, A','ha')}${field('sb','c','Runoff coefficient, C')}${field('sb','tc','Time of concentration, tc','min')}<label class="drain-field"><span>Rainfall station / IDF source</span><select name="stationId" required>${options(basin.stationId)}</select></label></div></fieldset><fieldset><legend>Storage & Geometry</legend><div class="drain-fields">${field('sb','settlingDepth','Settling-zone depth','m')}${field('sb','surfaceWidth','Surface width','m')}</div></fieldset><div id="sb-outlet-fields"></div><fieldset><legend>Emergency Spillway</legend><div class="drain-fields">${field('sb','spillwayWidth','Width, B','m')}${field('sb','spillwayHead','Design head, H','m')}${field('sb','spillwayCoefficient','Coefficient, Csp')}</div></fieldset><button class="table-trigger" type="button" data-criteria>View exact MSMA criteria and sizing tables</button><p id="sb-validation"></p></form><div class="drain-results"><section class="result-panel"><h2>Calculation Results</h2><div id="sb-results">Complete all inputs.</div></section><section class="result-panel"><h2>Cross-Section</h2><div id="sb-diagram">${basinDiagram({valid:false})}</div></section></div></div><section class="calculation-preview"><div class="drain-toolbar"><div><h2>Calculation Sheet</h2><p>5 A4 pages · Excel-style REF. / CALCULATION / REMARK format</p></div></div><div id="sb-report" class="escp-report"></div></section>${referenceDialogs()}`;const form=container.querySelector('form');form.oninput=e=>{if(!e.target.name)return;e.target.name==='stationId'?applyStation(basin,e.target.value):basin[e.target.name]=e.target.value;if(e.target.name==='basinType')renderTypeFields(container);updateBasin(container)};container.querySelector('#sb-print').onclick=()=>{document.body.classList.add('printing-escp');window.print()};bindDialog(container);renderTypeFields(container);updateBasin(container)}
function renderTypeFields(c){const t=c.querySelector('#sb-type-fields'),o=c.querySelector('#sb-outlet-fields');if(basin.basinType==='dry'){t.innerHTML=`<label class="drain-field" style="margin-top:14px"><span>Table 12.18 sizing duration, tc (min)</span><select name="sizingTc" required><option value="">Select duration</option>${Object.keys(dryTable).map(x=>`<option ${String(basin.sizingTc)===x?'selected':''}>${x}</option>`).join('')}</select></label>`;o.innerHTML=`<fieldset><legend>Primary Outlet (Riser)</legend><div class="drain-fields">${field('sb','orificeDiameter','Orifice diameter','m')}${field('sb','orificeCount','Number of orifices')}${field('sb','orificeHead','Head to orifice centre','m')}</div></fieldset>`}else if(basin.basinType==='wet'){t.innerHTML=`<label class="drain-field" style="margin-top:14px"><span>Runoff potential · Table 12.19</span><select name="runoffClass" required><option value="">Select runoff potential</option><option value="moderate" ${basin.runoffClass==='moderate'?'selected':''}>Moderate–high</option><option value="very-high" ${basin.runoffClass==='very-high'?'selected':''}>Very high</option></select></label>`;o.innerHTML=''}else{t.innerHTML='';o.innerHTML=''}}
function updateBasin(c){const r=calcBasin(basin);c.querySelector('#sb-print').disabled=!r.valid;c.querySelector('#sb-validation').textContent=r.valid?'':'Complete all red fields.';c.querySelector('#sb-results').innerHTML=r.valid?`<div class="drain-metrics"><div><span>Total storage</span><strong>${f(r.total)} <small>m³</small></strong></div><div><span>Settling / sediment</span><strong>${f(r.v1)} <small>m³ each</small></strong></div><div><span>Q10</span><strong>${f(r.q,3)} <small>m³/s</small></strong></div><div><span>Spillway</span><strong>${f(r.spill,3)} <small>m³/s</small></strong></div></div>${statusRows(r.checks)}`:'<p>Complete all inputs to calculate.</p>';c.querySelector('#sb-diagram').innerHTML=basinDiagram(r);c.querySelector('#sb-report').innerHTML=r.valid?basinReport(r):'';root.dispatchEvent(new CustomEvent('nadi:module-status',{detail:{key:'1/1',status:!r.valid?'incomplete':r.pass?'passed':'review'}}))}
function getState(){return {trap:{...trap},basin:{...basin}}}function restoreState(s){if(!s||typeof s!=='object')return false;trap={...trapDefaults,...(s.trap||{})};basin={...basinDefaults,...(s.basin||{})};return true}
if(root.addEventListener)root.addEventListener('afterprint',()=>document.body.classList.remove('printing-escp'));
root.ESCPDesign={mountTrap,mountBasin,getState,restoreState,calcTrap,calcBasin};
})(typeof window==='undefined'?globalThis:window);
